  "hints": [
   "A file needs the execute permission bit before `./file` will run it.",
   "`chmod +x launch.sh`, then run it with `./launch.sh`. Chain the two with `&&`."
  ],
  "learn": "Unix permissions are three triplets of read/write/execute bits for the owner, the group and\neveryone else (`rwxr-xr-x` = `755`). `chmod +x file` adds execute permission, after which\n`./file` runs it using the interpreter named in its first line (the `#!` \"shebang\").\n`cmd1 && cmd2` runs cmd2 only if cmd1 succeeded.",
  "solutions": [
   {
    "cmd": "chmod +x launch.sh && ./launch.sh",
    "note": "Reference solution"
   },
   {
    "cmd": "chmod u+x launch.sh; ./launch.sh",
    "note": "Execute permission for the owner (`u`) is all you need."
   },
   {
    "cmd": "chmod 755 launch.sh && ./launch.sh",
    "note": "Octal mode: rwx for you, r-x for everyone else. Sysadmin classic."
   },
   {
    "cmd": "chmod a+x ./launch.sh && \"$PWD/launch.sh\"",
    "note": "Executable for all, launched by absolute path. Mission control approves."
   }
  ],
  "timeLimit": 180,
