    "cmd": "l=abcdefghij; n=$(wc -l < giant.log); for ((i = 0; i * 200 < n; i++)); do tail -n +$((i * 200 + 1)) giant.log | head -n 200 > chunk_a${l:i:1}; done",
    "note": "Do it by hand with tail and head, one pigeon at a time."
